-- 22 novembre 2026 : Visale, ACRE, ARCE, Cart'Monétik. Nature précise (caution, réduction, capital, carte).
BEGIN;
UPDATE public.aides_reunion SET nom='Garantie Visale — caution locative gratuite',description_fr='La garantie Visale d''Action Logement est un cautionnement locatif gratuit pour certains locataires et logements. Elle peut couvrir des impayés ou dégradations selon contrat, mais ne paie pas le dépôt de garantie et n''est pas une aide en espèces. Conditions élargies en 2026.',description='La garantie Visale d''Action Logement est un cautionnement locatif gratuit pour certains locataires et logements. Elle peut couvrir des impayés ou dégradations selon contrat, mais ne paie pas le dépôt de garantie et n''est pas une aide en espèces. Conditions élargies en 2026.',
 demarches_fr='Vérifier son éligibilité sur le site Visale avant de signer un bail ; obtenir le visa puis suivre la procédure de validation avec le bailleur. Ne pas confondre avec l''Avance LOCA-PASS.',lien='https://www.actionlogement.fr/la-garantie-visale',lien_officiel='https://www.actionlogement.fr/la-garantie-visale',source_verification='https://www.actionlogement.fr/la-garantie-visale',
 statut_verification='source_confirmee',date_verification=DATE '2026-11-22',
 type_dispositif='service_gratuit',periode_validite='Source Action Logement 2026 ; les conditions d''âge, statut, logement et plafond varient selon les profils.',revenus_max=NULL,montant_min=NULL,montant_max=NULL
 WHERE id=31 AND actif;
UPDATE public.aides_reunion SET nom='ACRE — réduction de cotisations lors de la création d''entreprise',description_fr='L''ACRE n''est pas une somme versée : elle permet, si les conditions sont remplies, une exonération ou réduction temporaire de cotisations sociales pour un créateur ou repreneur. Les règles évoluent en 2026 ; le taux et la durée dépendent de la date de création et de la situation.',description='L''ACRE n''est pas une somme versée : elle permet, si les conditions sont remplies, une exonération ou réduction temporaire de cotisations sociales pour un créateur ou repreneur. Les règles évoluent en 2026 ; le taux et la durée dépendent de la date de création et de la situation.',
 demarches_fr='Consulter les règles en vigueur sur France Travail et l''Urssaf pour son activité, puis vérifier les démarches et dates applicables avant la création ou reprise.',lien='https://www.francetravail.fr/candidat/je-creereprends-une-entreprise/les-aides-financieres-creation-d/devenir-entrepreneur-les-aides-p.html',lien_officiel='https://www.francetravail.fr/candidat/je-creereprends-une-entreprise/les-aides-financieres-creation-d/devenir-entrepreneur-les-aides-p.html',source_verification='https://www.francetravail.fr/candidat/je-creereprends-une-entreprise/les-aides-financieres-creation-d/devenir-entrepreneur-les-aides-p.html',
 statut_verification='source_confirmee',date_verification=DATE '2026-11-22',
 type_dispositif='reduction_tarifaire',periode_validite='Règles 2026 modifiées selon la date de création ; ne pas calculer un taux universel.',revenus_max=NULL,montant_min=NULL,montant_max=NULL
 WHERE id=83 AND actif;
UPDATE public.aides_reunion SET nom='ARCE — capitalisation de droits ARE pour création d''entreprise',description_fr='ARCE : possibilité pour certains allocataires de France Travail créant ou reprenant une entreprise de recevoir une partie de leurs droits chômage restants sous forme de capital, sous conditions. Le choix et le cumul avec le maintien de l''ARE sont réglementés ; aucun capital n''est automatique.',description='ARCE : possibilité pour certains allocataires de France Travail créant ou reprenant une entreprise de recevoir une partie de leurs droits chômage restants sous forme de capital, sous conditions. Le choix et le cumul avec le maintien de l''ARE sont réglementés ; aucun capital n''est automatique.',
 demarches_fr='Faire étudier son projet et ses droits ARE auprès de France Travail ; vérifier les conditions de l''ACRE, le cumul possible et les modalités de demande avant de choisir entre maintien de l''ARE et ARCE.',lien='https://www.francetravail.fr/candidat/je-creereprends-une-entreprise/les-aides-financieres-creation-d/aide-a-la-reprise-et-a-la-creati.html',lien_officiel='https://www.francetravail.fr/candidat/je-creereprends-une-entreprise/les-aides-financieres-creation-d/aide-a-la-reprise-et-a-la-creati.html',source_verification='https://www.francetravail.fr/candidat/je-creereprends-une-entreprise/les-aides-financieres-creation-d/aide-a-la-reprise-et-a-la-creati.html',
 statut_verification='source_confirmee',date_verification=DATE '2026-11-22',
 type_dispositif='aide_financiere',periode_validite='Dispositif consulté en novembre 2026 ; calcul sur droits individuels et conditions 2026 à contrôler.',revenus_max=NULL,montant_min=NULL,montant_max=NULL
 WHERE id=84 AND actif;
UPDATE public.aides_reunion SET nom='Cart’Monétik — carte d''aide départementale 2026',description_fr='Aide départementale 2026 matérialisée par une carte de paiement utilisable auprès de commerçants équipés. Elle vise certains publics vulnérables suivant des conditions propres au Département, notamment bénéficiaires de dispositifs sociaux antérieurs. Ce n''est pas de l''argent librement versé en espèces.',description='Aide départementale 2026 matérialisée par une carte de paiement utilisable auprès de commerçants équipés. Elle vise certains publics vulnérables suivant des conditions propres au Département, notamment bénéficiaires de dispositifs sociaux antérieurs. Ce n''est pas de l''argent librement versé en espèces.',
 demarches_fr='Consulter la fiche Cart''Monétik du Département, vérifier les critères 2026 et les règles d''utilisation de la carte auprès du service départemental. Ne pas annoncer un crédit garanti sans confirmation de droits.',lien='https://www.departement974.fr/aide/aide-cartmonetik',lien_officiel='https://www.departement974.fr/aide/aide-cartmonetik',source_verification='https://www.departement974.fr/aide/aide-cartmonetik',
 statut_verification='source_confirmee',date_verification=DATE '2026-11-22',
 type_dispositif='aide_materielle',periode_validite='Cart''Monétik 2026 : critères et montants liés au public et au règlement, actualisation au moment de la demande.',revenus_max=NULL,montant_min=NULL,montant_max=NULL
 WHERE id=98 AND actif;
COMMIT;
SELECT id,nom,type_dispositif,statut_verification FROM public.aides_reunion WHERE id IN (31,83,84,98) ORDER BY id;